      var rowAliases=[h.label,h.ip,h.label+'@'+h.ip];for(var j=0;j<rowAliases.length;j++){var alias=rowAliases[j];if(aliases.has(alias)&&aliases.get(alias)!==i)return false;aliases.set(alias,i);}
      if(h.transport_outcome==='command_completed'&&h.returncode!==0||h.transport_outcome==='command_failed'&&(!integer(h.returncode,254)||h.returncode===0||h.returncode===124))return false;
