  function auth(){return [_currentUser,_currentRole,_csrfToken,_authToken,_authMode,_browserSessionActive,_startupReadSequence];}
  function path(node){var nodes=[];for(;node;node=node.parentNode)nodes.push(node);return nodes;}
  function same(nodes){return nodes.every(function(node,i){return node.parentNode===(nodes[i+1]||null);});}
