function _loadHomeFleetStats(mount){
  var auth=_captureFleetPollAuth();if(!auth())return;
  var ctx=_homeFleetStats.begin(mount);if(!ctx)return;
  function current(){return auth()&&ctx.current();}
  var vmView=ctx.views[4],vmOutput=_captureActivityOutput([vmView.root,vmView.root.firstElementChild,vmView.root.lastElementChild]);
  function vmCurrent(){if(!current()||!vmView.current()){if(vmOutput)vmOutput.dispose();return false;}return !!vmOutput&&vmOutput.current();}
  function publishVm(html){if(vmCurrent()){vmOutput.write(function(){vmView.publish(html);});vmOutput.dispose();}}
  var healthViews=ctx.views.slice(0,3),bodies=healthViews.map(function(v){return v.root&&v.root.firstElementChild;}),probe=ctx.probe;
  function healthCurrent(){return current()&&probe.parentNode===ctx.root&&healthViews.every(function(v,i){return v.current()&&bodies[i]&&bodies[i].parentNode===v.root;});}
  function publishHealth(value){
    if(!healthCurrent())return;
    var parts=_homeHealthObservation.build(value);
    if(!healthCurrent())return;
    healthViews.forEach(function(view,i){
      /* Fixed empty publication retains the private native navigation binding;
       * only detached literal nodes populate its already captured body. */
      view.publish('');bodies[i].replaceChildren(parts[i]);
    });
    probe.replaceChildren(parts[3]);
  }
  /* Siblings belong to this invocation, not to successful health decoding. */
  ctx.activityReady=true;
  if(vmCurrent())_authFetch(API.VMS,{readCurrent:vmCurrent}).then(function(r){return vmCurrent()?_viJSON(r):null;}).then(function(vd){
    if(vmCurrent())publishVm(_viHomeVmHtml(vd,_loadSettings().showTemplates===true));
  }).catch(function(){if(vmCurrent())publishVm(_viHomeVmHtml(null,false));});
  _authFetch(API.MEDIA_DASHBOARD,{silent:true,readCurrent:current}).then(function(r){return current()?_mediaJson(r,'dashboard'):null;}).then(function(md){
    if(current())ctx.views[5].publish(_mediaDashboardHtml(md));
  }).catch(function(){if(current())ctx.views[5].publish('Media observations unavailable. Counts unknown.');});
  _refreshFleetActivityWidgets();
  if(!healthCurrent())return;
  var receivedAt;
  _authFetch(API.HEALTH,{readCurrent:healthCurrent}).then(function(r){
    if(!healthCurrent())return null;
    receivedAt=Date.now();
    if(!r||r.status!==200||r.ok!==true||!r.headers||String(r.headers.get('Content-Type')||'').split(';')[0].trim().toLowerCase()!=='application/json')throw Error('Unsupported health response');
    return r.json();
  }).then(function(hd){
    if(!healthCurrent())return;
    var value=_homeHealthObservation.project(hd,receivedAt);
    if(healthCurrent())publishHealth(value);
  }).catch(function(){if(healthCurrent())publishHealth(null);});
}
function _loadWidgetOverview(){
  function literal(value){return _esc(String(value));}
  /* Populate physical device cards from fleet overview data */
  PROD_HOSTS.filter(function(h){return h.type!=='pve'}).forEach(function(h){
    var id='hw-'+h.label.toLowerCase().replace(/[^a-z0-9]/g,'-');
    var el=document.getElementById(id);if(!el)return;
    var c='';
    c+=_mrow('IP',literal(h.ip||'N/A'),0,'var(--purple-light)');
    c+=_mrow('ROLE',literal(h.role||h.type.toUpperCase()),0,'var(--purple-light)');
    if(h.detail)c+=_mrow('HARDWARE',literal(h.detail),0,'var(--text-dim)');
    el.innerHTML=c;
  });
  /* PVE summary */
  var tc=0,tr=0,tv=0,tctr=0;
  PROD_HOSTS.filter(function(h){return h.type==='pve'}).forEach(function(ph){tc+=ph.cores;tr+=(parseInt(ph.ram)||0);PROD_VMS.forEach(function(pv){if(pv.node===ph.label){tv++;tctr+=pv.containers;}});});
  var ps='';ps+=_mrow('TOTAL CPU',literal(tc+' Cores'),0,'var(--purple-light)');ps+=_mrow('TOTAL RAM',literal(tr+'GB'),0,'var(--blue)');ps+=_mrow('VMs',literal(tv),0,'var(--green)');ps+=_mrow('CONTAINERS',literal(tctr),0,'var(--cyan)');
  var pse=document.getElementById('hw-pve-sum');if(pse)pse.innerHTML=ps;
  /* VMs — exclude templates from counts */
  (function(){
    var auth=_captureFleetPollAuth(),owner=_beginMediaRead('home-overview-vms',['hw-vms']);
    if(!owner)return;
    function current(){if(!auth()){owner.dispose();return false;}return owner.current();}
    if(!current())return;
    _authFetch(API.VMS,{readCurrent:current}).then(function(r){return current()?_viJSON(r):null;}).then(function(d){
    if(!current())return;
    owner.nodes[0].innerHTML=_viHomeVmHtml(d,_loadSettings().showTemplates===true);owner.dispose();
  }).catch(function(){if(!current())return;owner.nodes[0].innerHTML=_viHomeVmHtml(null,false);owner.dispose();});
  })();
  /* Media */
  _loadMediaDashboard('hw-media');
}
