function createUnavailableStoragePresentation(document) {
  const root = document.createElement('section');
  root.setAttribute('aria-label', 'Storage observations');

  const heading = document.createElement('h2');
  heading.textContent = 'Storage observations';
  root.appendChild(heading);

  const summary = document.createElement('p');
  summary.textContent = 'Storage observations unavailable. No current storage selection is connected.';
  root.appendChild(summary);

  const configuration = document.createElement('section');
  configuration.setAttribute('aria-label', 'Storage configuration');
  const configurationHeading = document.createElement('h3');
  configurationHeading.textContent = 'Storage configuration';
  configuration.appendChild(configurationHeading);
  const configurationMessage = document.createElement('p');
  configurationMessage.textContent = 'Configuration unavailable. Storage types, paths, node restrictions and enabled state are unknown.';
  configuration.appendChild(configurationMessage);
  root.appendChild(configuration);

  const nodes = document.createElement('section');
  nodes.setAttribute('aria-label', 'Node storage observations');
  const nodesHeading = document.createElement('h3');
  nodesHeading.textContent = 'Node storage observations';
  nodes.appendChild(nodesHeading);
  const nodesMessage = document.createElement('p');
  nodesMessage.textContent = 'Node storage observations unavailable. Availability, reported counters, counter units and observation coverage are unknown.';
  nodes.appendChild(nodesMessage);
  root.appendChild(nodes);

  const content = document.createElement('section');
  content.setAttribute('aria-label', 'Storage content');
  const contentHeading = document.createElement('h3');
  contentHeading.textContent = 'Storage content';
  content.appendChild(contentHeading);
  const contentMessage = document.createElement('p');
  contentMessage.textContent = 'Content inventory unavailable. Item identities, types, sizes, dates and protection are unknown.';
  content.appendChild(contentMessage);
  root.appendChild(content);

  const disks = document.createElement('section');
  disks.setAttribute('aria-label', 'Physical disks');
  const disksHeading = document.createElement('h3');
  disksHeading.textContent = 'Physical disks';
  disks.appendChild(disksHeading);
  const disksMessage = document.createElement('p');
  disksMessage.textContent = 'Physical disk observations unavailable. Disk identities, usage and health are unknown.';
  disks.appendChild(disksMessage);
  root.appendChild(disks);

  const zfs = document.createElement('section');
  zfs.setAttribute('aria-label', 'ZFS pools');
  const zfsHeading = document.createElement('h3');
  zfsHeading.textContent = 'ZFS pools';
  zfs.appendChild(zfsHeading);
  const zfsMessage = document.createElement('p');
  zfsMessage.textContent = 'ZFS observations unavailable. Pool and vdev identities, topology, capacity, health and scrub status are unknown.';
  zfs.appendChild(zfsMessage);
  root.appendChild(zfs);

  const actions = document.createElement('p');
  actions.textContent = 'Configuration changes, content transfers, disk initialization and pool operations are unavailable.';
  root.appendChild(actions);
  return root;
}

