  if(kind==='hd'?_healthInFlight:_fleetInFlight)return;
  var ticket=_fleetReports.begin(kind,'scheduled',function(){return true;});if(!ticket)return;
  var flight={ticket:ticket},captured=_fleetReports.capture(kind);
