  ctx.fillStyle=fillColor||'rgba(168,85,247,0.08)';
  ctx.fill();
  /* Draw line */
  ctx.beginPath();
  vals.forEach(function(v,i){
    var x=pad+(points[i].t-firstTime)/timeRange*(w-pad*2);
    var y=h-pad-(v-mn)/range*(h-pad*2);
    if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
  });
