    return '<tr><td>'+_esc(c.domain||c.name||'-')+'</td><td>'+_esc(c.issuer||'-')+'</td><td>'+_esc(c.expires||c.not_after||'-')+'</td><td><span style="color:var(--'+color+')">'+_esc(dl)+'</span></td><td>'+_statusBadge(c.status||'unknown')+'</td></tr>';
