function _certStoreCloudflareToken(dryRun){
  var tokenEl=document.getElementById('cert-cloudflare-token')||{};
  var baseEl=document.getElementById('cert-provision-base-domain')||document.getElementById('cert-adopt-base-domain')||{};
  var replaceEl=document.getElementById('cert-cloudflare-token-replace')||{};
  var token=tokenEl.value||'';
  var base=baseEl.value||'';
  var replace=!!replaceEl.checked;
  if(!base.trim()){toast('Base domain is required before storing a token','error');try{baseEl.focus();}catch(e){}return;}
  if(!token.trim()){toast('Paste a Cloudflare DNS token first','error');try{tokenEl.focus();}catch(e){}return;}
  var body={base_domain:base.trim(),cloudflare_token:token.trim(),dry_run:dryRun,confirm:!dryRun,replace:replace};
  function run(){
    _certSetResult('<div class="skeleton h-60"></div>');
    _certPostJson(API.CERT_CLOUDFLARE_TOKEN,body).then(function(d){
      _certSetResult(_certRenderTokenStoreResult(d));
      if(d.ok){
        toast(dryRun?'Token validation complete':'Cloudflare token stored','success');
        if(!dryRun){
          tokenEl.value='';
          loadCertsPage();
        }
      }else toast(d.error||'Cloudflare token store failed','error');
    }).catch(function(e){_certSetResult('<div class="exec-out" style="color:var(--red)">'+_esc(e.toString())+'</div>');});
  }
  if(dryRun)run();
  else confirmAction('Store Cloudflare DNS token for <strong>'+_esc(base.trim())+'</strong>?<br>Review the API-reported validation and storage status after submitting.',run);
}
function _certBootstrap(dryRun){
  var baseEl=document.getElementById('cert-provision-base-domain')||document.getElementById('cert-base-domain')||{};
  var replaceEl=document.getElementById('cert-provision-replace')||document.getElementById('cert-bootstrap-replace')||{};
  var base=baseEl.value||'';
  var replace=!!replaceEl.checked;
  var last=_certLifecycleLast||{};
  var tokenPath=_certStoredCloudflareTokenPath(last.plan||{},last.onboarding||{});
  if(!base.trim()){toast('Base domain is required','error');try{baseEl.focus();}catch(e){}return;}
  if(!tokenPath){
    toast('Save the Cloudflare token before provisioning','error');
    var tokenEl=document.getElementById('cert-cloudflare-token');if(tokenEl)try{tokenEl.focus();}catch(e){}
    return;
  }
  function run(){
    _certSetResult('<div class="skeleton h-60"></div>');
    _certPostJson(API.CERT_BOOTSTRAP,{base_domain:base.trim(),cloudflare_token_path:tokenPath,replace:replace,dry_run:dryRun}).then(function(d){
      _certSetResult(_renderCertResult(d));
      if(d.ok){toast(dryRun?'Provision preview complete':'SSL provisioning applied','success');loadCertsPage();}
      else toast(d.error||'SSL provisioning failed','error');
    }).catch(function(e){_certSetResult('<div class="exec-out" style="color:var(--red)">'+_esc(e.toString())+'</div>');});
  }
  if(dryRun)run();
  else confirmAction('Apply SSL provisioning for <strong>'+_esc(base.trim())+'</strong>?<br>Review the provisioning result reported by the API after submitting.',run);
}
/* Certificate operations retain one original control/request/output lifetime. */
var _certPendingRequest=null;
var _certControlActions={certDnsDryRun:['dns-sync',true],certDnsApply:['dns-sync',false],
  certIssueDryRun:['issue',true],certIssueApply:['issue',false],certRenewDryRun:['renew',true],
  certRenewApply:['renew',false],certDeployDryRun:['deploy',true],certDeployApply:['deploy',false],
  certVerify:['verify',false],certReconcile:['reconcile',false]};
function _certRetireRequest(){if(_certPendingRequest)_certPendingRequest.retire();_certPendingRequest=null;}
function _certNodePath(node){var path=[];while(node){path.push(node);node=node.parentNode;}return path;}
function _certVisible(node){
  return !!node&&node.isConnected&&node.getClientRects().length>0&&_certNodePath(node).every(function(n){
    if(n.nodeType!==1)return true;
    var style=getComputedStyle(n);
    return !n.hidden&&!n.inert&&!n.hasAttribute('disabled')&&n.getAttribute('aria-disabled')!=='true'&&style.display!=='none'&&style.visibility==='visible';
  });
}
function _certBindActionControls(){
  ['cert-setup','cert-actions'].forEach(function(id){
    var root=document.getElementById(id);if(!root)return;
    root.querySelectorAll('button[data-action]').forEach(function(button){
      var spec=_certControlActions[button.dataset.action];if(!spec)return;
      var parent=button.parentNode;
      button.type='button';
      button.addEventListener('click',function(e){
        e.preventDefault();e.stopImmediatePropagation();
        if(button.parentNode!==parent||!root.contains(button)||!_certVisible(button))return;
        _certAction(spec[0],spec[1],button);
      });
    });
  });
}
function _certCaptureRequest(button,body){
  _certRetireRequest();
  var selector=document.getElementById('cert-action-target'),view=document.getElementById('certs-view');
  var outputs=['cert-result','cert-result-inline'].map(function(id){return document.getElementById(id);}).filter(_certVisible);
  if(_currentView!=='certs'||!_browserSessionActive||!view||!view.contains(button)||!_certVisible(button)||!_certVisible(selector)||!outputs.length)return null;
  var context=[_currentUser,_currentRole,_csrfToken,_authMode,_authToken,_browserSessionActive];
  var nodes=[button,selector].concat(outputs),paths=nodes.map(_certNodePath),ids=nodes.map(function(n){return n.id;});
  var contents=outputs.map(function(n){return n.innerHTML;}),selection=selector.value,live=true,dispatched=false;
  var observer=new MutationObserver(changed);
  function retire(){live=false;observer.disconnect();selector.removeEventListener('input',retire);selector.removeEventListener('change',retire);}
  function changed(records){records.forEach(function(record){
    if(record.type==='attributes'&&paths.some(function(path){return path.indexOf(record.target)>=0;}))retire();
    if(record.type==='characterData'&&outputs.some(function(n){return n.contains(record.target);}))retire();
    if(record.type==='childList'){
      if(outputs.indexOf(record.target)>=0||outputs.some(function(n){return n.contains(record.target);}))retire();
      record.removedNodes.forEach(function(removed){if(paths.some(function(path){return path.some(function(n){return removed===n||(removed.contains&&removed.contains(n));});}))retire();});
    }
  });}
  function watch(){observer.observe(document.body,{childList:true,characterData:true,subtree:true,attributes:true,attributeFilter:['id','class','style','hidden','inert','disabled','aria-disabled','data-action']});}
  function current(){
    changed(observer.takeRecords());
    var now=[_currentUser,_currentRole,_csrfToken,_authMode,_authToken,_browserSessionActive];
    if(!live||_currentView!=='certs'||!context.every(function(v,i){return v===now[i];})||selector.value!==selection)return false;
    return nodes.every(function(node,i){
      var path=_certNodePath(node);
      return _certVisible(node)&&node.id===ids[i]&&(!ids[i]||(document.querySelectorAll('[id="'+ids[i]+'"]').length===1&&document.getElementById(ids[i])===node))&&path.length===paths[i].length&&path.every(function(n,j){return n===paths[i][j];});
    })&&outputs.every(function(n,i){return n.innerHTML===contents[i];});
  }
  function write(html){if(!current())return false;observer.disconnect();outputs.forEach(function(n){n.innerHTML=html;});contents=outputs.map(function(n){return n.innerHTML;});watch();return true;}
  watch();selector.addEventListener('input',retire);selector.addEventListener('change',retire);_onViewCleanup(retire);
  var ticket={retire:retire,current:current,write:write,start:function(){if(dispatched||!current())return false;dispatched=true;return true;}};
  _certPendingRequest=ticket;return ticket;
}
function _certObject(d){return !!d&&typeof d==='object'&&!Array.isArray(d);}
