      if(!_certObject(t)||typeof t.target!=='string'||!t.target||seen[t.target]||allowed.indexOf(t.outcome)<0||t.tls_verification!=='not_performed'||!Array.isArray(t.steps))throw new Error('Invalid deployment target evidence');
      seen[t.target]=true;
      if(body.target&&t.target!==body.target)throw new Error('Deployment target differs from the approved target');
      if((body.dry_run&&(['planned','unsupported'].indexOf(t.outcome)<0||t.effects!==undefined))||(!body.dry_run&&t.outcome==='planned'))throw new Error('Deployment mode differs from the approved request');
      if(t.unattempted_steps!==undefined&&(!Number.isInteger(t.unattempted_steps)||t.unattempted_steps<0))throw new Error('Invalid unattempted step count');
