/* Helper: fetch JSON and invoke render callback */
function _fetchAndRender(url,statsId,renderFn,contentIds){
  var el=document.getElementById(statsId);
  var generation=(el&&el._freqRequestGeneration||0)+1;
  if(el)el._freqRequestGeneration=generation;
  var targets=[statsId].concat(contentIds||[]).map(function(id){return document.getElementById(id);}).filter(Boolean);
  targets.forEach(function(target){if(target!==el)target._freqRequestGeneration=(target._freqRequestGeneration||0)+1;target._freqRequestOwner=url;});
  var targetGenerations=targets.map(function(target){return target._freqRequestGeneration;});
  if(el)el.innerHTML='<div class="skeleton h-40"></div>';
  _authFetch(url).then(function(r){
    if(!r.ok)throw new Error('HTTP '+r.status);
    return r.json();
  }).then(function(d){
    if(el&&el._freqRequestGeneration!==generation)return;
    if(targets.some(function(target,index){return target._freqRequestOwner!==url || !target.isConnected || target._freqRequestGeneration!==targetGenerations[index];}))return;
    if(!d||typeof d!=='object'||Array.isArray(d))throw new Error('Invalid response schema');
    if(_renderUnavailableCapability(d,[statsId].concat(contentIds||[]),url))return;
    renderFn(d);
  }).catch(function(e){
    if(el&&el._freqRequestGeneration!==generation)return;
    if(targets.some(function(target,index){return target._freqRequestOwner!==url || !target.isConnected || target._freqRequestGeneration!==targetGenerations[index];}))return;
    if(el)el.innerHTML='<div class="exec-out" style="color:var(--red)">Failed to load: '+_esc(e.toString())+'</div>';
  });
}
function _renderUnavailableCapability(data,ids,owner){
  if(!data || !(data.implemented===false || data.available===false || data.capability_status==='unimplemented'))return false;
  var message=(data.implemented===false || data.capability_status==='unimplemented')
    ? 'This capability is not implemented. No live data is available.'
    : 'This capability is unavailable. No live data is available.';
  ids.forEach(function(id){
    var el=document.getElementById(id);if(!el)return;
    /* A shared panel may have newer data from its independent action endpoint. */
    if(owner&&el._freqResponseOwner&&el._freqResponseOwner!==owner)return;
    if(el.tagName==='TBODY'){
      var row=document.createElement('tr'),cell=document.createElement('td');
      var table=el.closest('table');
      cell.colSpan=table?Math.max(1,table.querySelectorAll('thead th').length):1;
      cell.textContent=message;row.appendChild(cell);el.replaceChildren(row);
    }else el.textContent=message;
    if(owner)el._freqResponseOwner=owner;
  });
  return true;
}
