function loadBackupPolicies(){
  if(!_backupPolicyControl.current())return;
  var owner=_beginBackupRead('policies',['backup-policy-list','backup-policy-stats',_backupPolicyControl.button]);if(!owner)return;
  var list=owner.nodes[0],stats=owner.nodes[1];
  var policyCurrent=_backupPolicyControl.current;
  function current(){return owner.current()&&policyCurrent();}
  function write(fn){if(_backupPolicyControl.current())owner.write(fn);}
  write(function(){list.textContent='Reading saved policy definitions…';stats.textContent='Reading saved enforcement counters…';});
  function read(url,out,withState){
    if(!current())return;
    _authFetch(url,{silent:true,readCurrent:current}).then(function(r){if(!current())return null;return r.json().then(function(d){return {data:d,status:r.status};});}).then(function(reply){
      if(!current())return;
      if(!_backupTruth.policy(reply.data,reply.status,withState))throw new Error();var d=reply.data;
      write(function(){out.replaceChildren();
        if(!withState){
          if(d.policies===null)_backupElement(out,'p','Saved policy definitions unavailable. No empty policy list established.');
          else {
            _backupElement(out,'p',d.count===0?'Observed empty saved policy file.':d.count+' saved policy definition(s).');
            if(d.count)_backupTable(out,['Name','Stored interval','Stored retention','Target / type','Enabled','Stored created label'],d.policies.slice(0,100).map(function(p){return [p.name,p.interval===undefined?'Unknown':p.interval,p.retention===undefined?'Unknown':p.retention,(p.target===undefined?'Unknown':p.target)+' / '+(p.target_type===undefined?'Unknown':p.target_type),p.enabled===undefined?'Unknown':p.enabled?'Yes':'No',p.created===undefined?'Unknown':p.created];}));
            if(d.count>100)_backupElement(out,'p','Showing the first 100 definitions.');
            _backupElement(out,'p','Policy file revision: '+d.policy_revision);
          }
          _backupElement(out,'p','Stored interval and retention are settings, not verified scheduling, units or compliance. Missing fields remain unknown.');
        }else{
          _backupElement(out,'p',d.complete?'Saved policy and counter files observed.':'Saved policy/counter observation incomplete; available components are shown independently.');
          _backupElement(out,'p','Policy count in this status read: '+(d.policy_count===null?'Unknown':d.policy_count)+'.');
          if(d.state===null)_backupElement(out,'p','Saved enforcement counters unavailable. Last run, created and pruned counts are unknown.');
          else {_backupTable(out,['Stored last-run label','Cumulative created','Cumulative pruned'],[[d.last_run,d.snapshots_created,d.snapshots_pruned]]);_backupElement(out,'p','State file revision: '+d.state_revision);}
          if(d.policy_revision!==null)_backupElement(out,'p','Policy revision in status read: '+d.policy_revision);
          _backupElement(out,'p','Counters are retained cumulative enforcement claims, not current coverage or successful recovery. File revisions and the separate list read do not form one transaction.');
        }
        _backupElement(out,'p','Source: saved policy files. Freshness, compliance and recoverability are not assessed.');
      });
    }).catch(function(){if(!current())return;write(function(){out.textContent=withState?'Saved enforcement observation unavailable: invalid or failed response. Counts and last run remain unknown.':'Saved policy observation unavailable: invalid or failed response. No empty policy list established.';});});
  }
  read(API.BACKUP_POLICY_LIST,list,false);read(API.BACKUP_POLICY_STATUS,stats,true);
}

