function termCopy(){
  if(!_termXterm)return;
  var sel=_termXterm.getSelection();
  if(sel){
    navigator.clipboard.writeText(sel).then(function(){toast('Copied to clipboard','success');});
  }else{toast('Nothing selected','info');}
}

function termPaste(){
  if(!_termXterm)return;
  navigator.clipboard.readText().then(function(text){
    if(_termSocket&&_termSocket.readyState===WebSocket.OPEN){
      _termSocket.send(new TextEncoder().encode(text));
    }
  }).catch(function(){toast('Clipboard access denied','error');});
}

/* Terminal target picker */
var _terminalTargetRequests=(function(){
  var latest=null,cleanupHooked=false;
  function foreignId(node,id){return (id==='term-type'&&node!==latest.typeControl)||(id==='term-target'&&node!==latest.select);}
  function collision(node){
    if(!node||node.nodeType!==1)return;
    if(foreignId(node,node.id))latest.live=false;
    node.querySelectorAll('[id="term-type"],[id="term-target"]').forEach(function(el){if(foreignId(el,el.id))latest.live=false;});
  }
  function removed(records){if(!latest)return;records.forEach(function(record){
    if(record.type==='attributes'){
      if(foreignId(record.target,record.oldValue)||foreignId(record.target,record.target.id)||record.target===latest.typeControl||record.target===latest.select)latest.live=false;
      return;
    }
    record.addedNodes.forEach(collision);
    record.removedNodes.forEach(function(node){
      collision(node);
      if(latest.paths.some(function(path){return path.some(function(original){return node===original||(node.contains&&node.contains(original));});}))latest.live=false;
    });
  });}
  var observer=new MutationObserver(removed);observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['id'],attributeOldValue:true});
  return {begin:function(typeControl,select,type,view){
    removed(observer.takeRecords());if(latest)latest.live=false;
    var ticket={typeControl:typeControl,select:select,type:type,view:view,live:true,paths:[],auth:_captureFleetPollAuth()};latest=ticket;
    [typeControl,select].forEach(function(control){var path=[],node=control;while(node&&node!==document){path.push(node);node=node.parentNode;}if(node!==document)ticket.live=false;ticket.paths.push(path);});
    if(!cleanupHooked){cleanupHooked=true;_onViewCleanup(function(){if(latest)latest.live=false;cleanupHooked=false;});}
    return function(){
      removed(observer.takeRecords());
      return latest===ticket&&ticket.live&&ticket.auth()&&_currentView===view&&typeControl.value===type&&['vm','ct','node','host','pfsense','truenas','idrac','switch'].indexOf(type)>=0&&
        document.getElementById('term-type')===typeControl&&document.getElementById('term-target')===select&&document.querySelectorAll('#term-type').length===1&&document.querySelectorAll('#term-target').length===1&&
        [typeControl,select].every(function(control,index){return control.tagName==='SELECT'&&!control.multiple&&control.size===0&&control.form===null&&!control.matches(':disabled')&&control.getAttribute('aria-disabled')!=='true'&&!control.closest('[inert]')&&control.getClientRects().length>0&&
          ticket.paths[index].every(function(node,i){return node.parentNode===(ticket.paths[index][i+1]||document);})&&_ownedControlPathVisible(ticket.paths[index]);});
    };
  }};
})();
function updateTermTargets(){
  var typeControl=document.getElementById('term-type'),sel=document.getElementById('term-target');if(!typeControl||!sel)return Promise.resolve(false);
  var type=typeControl.value,predicate;
  try{predicate=_terminalTargetRequests.begin(typeControl,sel,type,_currentView);}catch(e){return Promise.resolve(false);}
  function current(){try{return typeof predicate==='function'&&predicate()===true;}catch(e){return false;}}
  if(!current())return Promise.resolve(false);
  function text(value){return value?String(value):'';}
  function option(value,label,targetLabel,hostType){
    var node=document.createElement('option');node.value=String(value);node.textContent=label;
    if(arguments.length>2)node.setAttribute('data-label',targetLabel);
    if(arguments.length>3)node.setAttribute('data-htype',hostType);
    return node;
  }
  function publish(label,build){
    if(!current())return false;
    var fragment=document.createDocumentFragment();fragment.appendChild(option('',label));if(build)build(fragment);
    if(!current())return false;sel.replaceChildren(fragment);return true;
  }
  function rows(data,key){if(!data||typeof data!=='object'||data.ok===false||data.error)throw new Error('Targets unavailable');var items=data[key];if(items==null)return [];if(!Array.isArray(items))throw new Error('Targets unavailable');return items;}
  function nodes(data){return publish('Select node...',function(fragment){rows(data,'pve_nodes').forEach(function(n){var dn=_displayName(n);fragment.appendChild(option(text(n.ip),text(dn)+' ('+text(_secondaryIdentity(n)||n.ip)+')',text(n.name)));});});}
  function failure(){return current()?publish('Unable to load targets'):false;}
  function load(url,render){return Promise.resolve().then(function(){if(!current())return null;return _authFetch(url,{readCurrent:current});}).then(function(response){
    if(!current())return null;if(!response||response.ok===false)throw new Error('Targets unavailable');return response.json();
  }).then(function(data){return current()?render(data):false;}).catch(function(){failure();return false;});}
  publish('Loading...');
  if(type==='vm')return load(API.VMS,function(data){return publish('Select VM...',function(fragment){rows(data,'vms').forEach(function(v){if(v.status==='running')fragment.appendChild(option(v.vmid,String(v.vmid)+' — '+text(v.name)+' ('+String(v.node)+')',text(v.name)));});});});
  if(type==='ct')return load(API.CT_LIST,function(data){return publish('Select CT...',function(fragment){rows(data,'containers').forEach(function(c){if(c.status==='running')fragment.appendChild(option(c.ctid,'CT '+String(c.ctid)+' — '+text(c.name)+' ('+String(c.node)+')','CT '+String(c.ctid)+' '+text(c.name)));});});});
  if(type==='node'){
    if(_fleetCache.fo&&_fleetCache.fo.pve_nodes){try{return Promise.resolve(nodes(_fleetCache.fo));}catch(e){failure();return Promise.resolve(false);}}
    return load(API.FLEET_OVERVIEW,nodes);
  }
  var device=['pfsense','truenas','idrac','switch'].indexOf(type)>=0;
  return load(API.HEALTH,function(data){return publish(device?'Select device...':'Select host...',function(fragment){rows(data,'hosts').forEach(function(h){
    if(!device||h.type===type)fragment.appendChild(option(text(h.ip),text(h.label)+' ('+text(h.ip)+')',text(h.label),text(device?h.type:(h.type||'linux'))));
  });});});
}
function launchTermFromPicker(){
  var type=document.getElementById('term-type').value;
  var sel=document.getElementById('term-target');
  var target=sel.value;
  if(!target){toast('Select a target','error');return;}
  var opt=sel.options[sel.selectedIndex];
  var label=opt.getAttribute('data-label')||target;
  var htype=opt.getAttribute('data-htype')||type;
  /* Infrastructure/host entries are already IP targets. Do not send them
     through VMID resolution, or the terminal can fail on valid core-device cards. */
  var termType=(type==='pfsense'||type==='truenas'||type==='idrac'||type==='switch'||type==='host')?'host':type;
  openTerminal(termType,target,'',label,htype);
}

