function doCtCreate(){
  var tpl=document.getElementById('ct-create-tpl').value.trim();
  var name=document.getElementById('ct-create-name').value.trim();
  var cores=document.getElementById('ct-create-cores').value;
  var ram=document.getElementById('ct-create-ram').value;
  var disk=document.getElementById('ct-create-disk').value;
  var out=document.getElementById('ct-tool-out');
  if(!tpl||!name){toast('Template and hostname required','error');return;}
  if(out)out.innerHTML='<div class="c-yellow">Creating container...</div>';
  /* POST + JSON body. Pre-fix this used GET ?template=...&hostname=... which
   * always 405d because the server requires POST. R-SECURITY-TRUST-AUDIT-20260413P
   * F5 fixed both: server reads from JSON body so the optional password field
   * never lands in URL leak channels, and the dashboard finally talks to it
   * with the right method. */
  _authFetch(API.CT_CREATE,{method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({template:tpl,hostname:name,cores:cores,ram:ram,disk:disk})})
  .then(function(r){return r.json()}).then(function(d){
      if(d&&d.ok===true){
        toast('Container create: reported success; completion unverified','info');
        if(out)out.innerHTML='<div class="c-green">REPORTED SUCCESS — '+'Container CT '+_esc(''+d.ctid)+' ('+_esc(d.hostname)+')'+'</div><div class="c-dim">Target state and completion are not verified.</div>';
        refreshLxcWorkloads();
      }else if(d&&d.ok===false){
        toast('Container create: reported failure; completion unverified','error');
        if(out)out.innerHTML='<div class="c-red">REPORTED FAILURE</div><div class="c-dim">Target state and completion are not verified.</div><div class="c-dim">'+_esc(d.error||'No error detail returned')+'</div>';
      }else{
        if(out)out.innerHTML='<div class="c-yellow">OUTCOME UNVERIFIED</div><div class="c-dim">No boolean command outcome was returned. Target state and completion are not verified.</div>';
      }
    }).catch(function(e){if(out)out.innerHTML='<div class="c-red">'+_esc(e.toString())+'</div>';});
}
