    ['node','vm'].forEach(function(k){var o=d.observations[k];h+='<div>'+k+': '+_esc(o.observation)+'; source '+_esc(o.selected_source)+'; collection '+_planDate(o.observed_at)+'; excluded '+_planValue(o.excluded_count===undefined?null:o.excluded_count)+'; malformed '+_planValue(o.malformed_rows===undefined?null:o.malformed_rows)+'.</div>';});
