    if(d.nodes.length){h+='<table><thead><tr><th>Node</th><th>CPU %</th><th>RAM %</th><th>RAM used GB</th><th>RAM total GB</th></tr></thead><tbody>';d.nodes.forEach(function(n){h+='<tr><td>'+_esc(n.node)+'</td><td>'+n.cpu_pct+'</td><td>'+n.mem_pct+'</td><td>'+n.mem_used_gb+'</td><td>'+n.mem_total_gb+'</td></tr>';});h+='</tbody></table>';}
