function updatePref(key,val){
  if(typeof key!=='string'||typeof val!=='string')return;
  var values=key==='refresh'?['0','10','30','60','120']:key==='density'?['compact','normal','comfortable']:null;
  if(!values||values.indexOf(val)<0)return;
  localStorage.setItem(key==='refresh'?'freq_refresh':'freq_density',val);
  if(key==='refresh'){
    if(window._autoRefreshTimer)clearInterval(window._autoRefreshTimer);
    var ms=parseInt(val)*1000;
    if(ms>0)window._autoRefreshTimer=setInterval(function(){refreshCurrentView();},ms);
  }
  toast('Preference saved: '+key+' = '+val,'ok');
}
/* ── Device Assignment — classify fleet members for dashboard grouping ── */
