function _replaceDeviceAssignmentRows(el,html){
  /* A save can refresh this table while another row is being edited. Keep
   * only changed fields, keyed to the same device, rather than restoring an
   * entire stale row over newly fetched inventory. Never dispatch a save. */
  var drafts=new Map(),focused=document.activeElement,focusKey=null;
  function controls(root,visit){
    root.querySelectorAll('tr').forEach(function(row){
      var save=row.querySelector('[data-action="saveDeviceAssignmentRow"]');
      if(!save)return;
      var identity=[save.dataset.source,save.dataset.label,save.dataset.device,save.dataset.vmid];
      row.querySelectorAll('input[id],select[id]').forEach(function(control){
        visit(control,JSON.stringify(identity.concat(control.id)));
      });
    });
  }
  controls(el,function(control,key){
    var initial=control.defaultValue;
    if(control.tagName==='SELECT'){
      var options=Array.from(control.options);
      var selected=options.find(function(option){return option.defaultSelected;})||options[0];
      initial=selected?selected.value:'';
    }
    if(control.value!==initial)drafts.set(key,control.value);
    if(control===focused)focusKey=key;
  });
  el.innerHTML=html;
  controls(el,function(control,key){
    if(drafts.has(key)){
      var value=drafts.get(key);
      if(control.tagName!=='SELECT'||Array.from(control.options).some(function(option){return option.value===value;}))control.value=value;
    }
    if(key===focusKey)control.focus({preventScroll:true});
  });
}
/* Two independently revisioned local files; never adoption or live inventory. */
