  return Object.values(s.physical).every(function(p){return _assignmentKeys(p,['ip','label','type','display_name','detail','groups','scope','tier'])&&Object.values(p).every(_assignmentText)&&(!('scope'in p)||['core','lab'].includes(p.scope));});
