  if(a)Object.entries(a.physical).forEach(function(pair){rows.push({kind:'physical',key:JSON.stringify(['physical',pair[0]]),device:pair[0],label:pair[1].label||pair[0],address:pair[1].ip||'',saved:pair[1],revision:a.revision});});
  if(o){var ids=new Map();o.components.vms.rows.forEach(function(vm){ids.set(vm.vmid,(ids.get(vm.vmid)||0)+1);});o.components.vms.rows.forEach(function(vm,index){
    var memberships=a?Object.keys(a.categories).filter(function(k){return (a.categories[k].vmids||[]).includes(vm.vmid);}):[];
    var ranges=a?Object.keys(a.categories).filter(function(k){var c=a.categories[k];return 'range_start'in c&&vm.vmid>=c.range_start&&vm.vmid<=c.range_end;}):[];
    rows.push({kind:'vm',key:JSON.stringify(['vm',vm.vmid,vm.node||'',index]),label:vm.name,address:vm.node||'',vmid:vm.vmid,saved:vm,revision:a&&a.revision,memberships:memberships,ranges:ranges,ambiguous:ids.get(vm.vmid)!==1});
  });}
