function loadMetricsQuick(){
  var read=_quickCt.begin();if(!read)return;
  var roots=_quickCt.roots;
  try{
    if(_fleetCache.fo||_fleetCache.hd){
      _renderFleetData(_fleetCache.fo,_fleetCache.hd,_fleetCache.md,_quickCt.snapshot(read.grant,_fleetCache.fo,_fleetCache.hd),false,read.grant);
    }else{
      _quickCt.html(read.grant,roots['metrics-cards'],'<div class="skeleton"></div>');
      _quickCt.html(read.grant,roots['metrics-summary'],'<div class="skeleton h-50"></div>');
      _quickCt.evidence(read.grant,null,null);
    }
    if(!read.current()){read.end();return;}
    // Eager rendering is complete before these fresh request owners exist.
    var mediaOwner=_beginMediaRead('fleet-media',['metrics-cards']);
    var summaryOwner=_captureFleetSummaryRead();
    if(!mediaOwner||mediaOwner.nodes[0]!==roots['metrics-cards']||!mediaOwner.current()||!summaryOwner.current())throw new Error('owner');
    read.attach(function(){mediaOwner.dispose();});
    if(!read.pending())return;
    function current(){return read.current()&&mediaOwner.current()&&summaryOwner.current();}
    var overviewTicket=_fleetReports.begin('fo','quick',current),healthTicket=_fleetReports.begin('hd','quick',current);
    function media(){return _authFetch(API.MEDIA_STATUS,{silent:true,readCurrent:current}).then(function(r){return current()?_mediaJson(r,'status'):null;}).then(function(d){return current()?d:null;}).catch(function(){return null;});}
    function ct(){return _authFetch(API.CT_LIST,{silent:true,readCurrent:current}).then(function(r){
      if(!current()||r.status!==200||r.ok!==true||!/^application\/json(?:\s*;|\s*$)/i.test(r.headers.get('content-type')||'')||typeof r.json!=='function')return null;
      var json=r.json;if(!current()||typeof json!=='function')return null;return json.call(r);
    }).then(function(d){return current()?window.FreqQuickCt.decode(d):null;}).catch(function(){return null;});}
    Promise.all([_fleetReports.request(overviewTicket,API.FLEET_OVERVIEW),_fleetReports.request(healthTicket,API.HEALTH),media(),ct()]).then(function(results){
      if(!read.current())return;
      var summaryCurrent=summaryOwner(); // exactly one terminal consumption
      if(!summaryCurrent||!mediaOwner.current()||!read.current())return;
      mediaOwner.dispose(); // own render must not recheck a disposed helper
      var grant=read.terminal(true,results[3]);if(!grant)return;
      function allowed(){return _quickCt.allowed(grant);}
      if(!_infraNative.replaceForQuick(grant))return;
      var fo=_fleetReports.commit(overviewTicket,results[0],allowed),hd=_fleetReports.commit(healthTicket,results[1],allowed);
      if(fo)_fleetReportDiagnostic(overviewTicket,results[0],allowed);
      if(hd)_fleetReportDiagnostic(healthTicket,results[1],allowed);
      if(!allowed())return;
      _fleetCache.md=_payloadHasError(results[2])?null:results[2];
      _renderFleetData(_fleetCache.fo,_fleetCache.hd,_fleetCache.md,_quickCt.snapshot(grant,_fleetCache.fo,_fleetCache.hd),false,grant);
    }).catch(function(){var grant=read.failed();if(grant)_quickCt.evidence(grant,_fleetCache.fo,_fleetCache.hd);}).finally(read.end);
  }catch(e){var grant=read.failed();if(grant)_quickCt.evidence(grant,_fleetCache.fo,_fleetCache.hd);read.end();}
}
