  h+='<div class="lab-role-top"><div><h3 class="lab-title" style="color:'+color+'">'+_esc(label)+'</h3><div class="lab-meta">'+_esc(meta||'')+' \u00b7 <span class="fleet-report-state '+statusClass+'">'+_esc(status||'UNKNOWN')+'</span></div></div><span class="lab-kind">'+_esc(kind)+'</span></div>';
  h+='<div class="lab-metrics">';
