    if(!ambiguous&&nd.vmRows&&nd.vmRows.length){var table=group.querySelector('.pve-workload-table'),head=table&&table.firstElementChild;if(!head)throw Error('Original VM row insertion unavailable');head.after.apply(head,nd.vmRows);}
