// A completed command observation is not a migration or mutation authorization.
function _readSnapshotInventory(vmid){
  return _authFetch(API.VM_SNAPSHOTS+'?vmid='+encodeURIComponent(vmid),{silent:true}).then(function(r){
    return r.json().then(function(d){
      if(!r.ok||!d||d.ok!==true||d.inventory_state!=='complete')throw Error(d&&d.error||'Snapshot inventory unavailable');
      if(!Number.isSafeInteger(d.vmid)||d.vmid!==Number(vmid)||!Array.isArray(d.snapshots)||
         !d.snapshots.every(function(n){return typeof n==='string'&&n.length>0;})||
         new Set(d.snapshots).size!==d.snapshots.length||!Number.isSafeInteger(d.count)||d.count!==d.snapshots.length||
         typeof d.observed_at!=='number'||!Number.isFinite(d.observed_at)||d.observed_at<=0||d.observed_at>8640000000000)
        throw Error('Invalid snapshot inventory response');
      return d;
    });
  });
}


function _showSnapshotInventory(out,vmid,controls,isCurrent){
  if(!out)return;
  var token={},card=_cardState;
  out._snapshotRequest=token;
  var previous=out._snapshotInventory;
  var loading=document.createElement('span');loading.textContent='Loading snapshots...';out.replaceChildren(loading);
  function current(){return out.isConnected&&out._snapshotRequest===token&&out.contains(loading)&&
    (!isCurrent||isCurrent())&&(!controls||card===_cardState);}
  return _readSnapshotInventory(vmid).then(function(d){
    if(!current())return;
    out._snapshotInventory=d;out.replaceChildren();
    var heading=document.createElement('div');heading.textContent=d.count?d.count+' snapshots':'No snapshots';out.appendChild(heading);
    d.snapshots.forEach(function(name){
      var row=document.createElement('div'),label=document.createElement('span');label.textContent=name;row.appendChild(label);
      out.appendChild(row);
    });
    if(controls){var note=document.createElement('div');note.textContent='Snapshot changes unavailable. Verified VM identity, snapshot tree and operation admission are required. Snapshots are not backup archives.';out.appendChild(note);}
  }).catch(function(e){
    if(!current())return;
    out.replaceChildren();var error=document.createElement('div');error.className='c-red';
    error.textContent='Snapshot inventory unavailable: '+e.message;out.appendChild(error);
    if(previous&&previous.vmid===Number(vmid)){
      var stale=document.createElement('pre');stale.textContent='Previous observation (stale): '+new Date(previous.observed_at*1000).toISOString()+'\n'+
        (previous.snapshots.join('\n')||'No snapshots at that observation');out.appendChild(stale);
    }
  });
}
