function _rebootPost(url,label){
  var out=_writeOut();if(!out)return;
  var card=_cardState,marker=document.createElement('span');
  marker.textContent='Submitting '+label+' command...';out.replaceChildren(marker);
  function current(){return out.isConnected&&card===_cardState&&out.contains(marker);}
  function show(text,kind){if(!current())return;marker.className=kind;marker.textContent=text;}
  return _authFetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:true})})
    .then(function(r){return r.json().then(function(d){
      if(r.ok&&d&&d.ok===true&&d.submission_state==='acknowledged'&&d.reboot_state==='unverified'&&d.returncode===0){
        show(label+': command acknowledged. Reboot and recovery have not been verified.','c-yellow');
      }else if([400,401,403,405].indexOf(r.status)!==-1&&d&&d.error){
        show(label+': request refused. '+String(d.error),'c-red');
      }else{
        show(label+': command outcome unknown. Reboot and recovery have not been verified.'+(d&&d.error?' '+String(d.error):''),'c-yellow');
      }
    });}).catch(function(e){show(label+': command outcome unknown. Reboot and recovery have not been verified. '+e.message,'c-yellow');});
}
function tnReboot(){
  if(!confirm('REBOOT TrueNAS? All services will be interrupted!'))return;
  if(!confirm('Are you REALLY sure? This will take the storage offline.'))return;
  _rebootPost(API.TRUENAS_REBOOT,'TrueNAS reboot');
}

