function vmDestroy(vmid){
  /* M-BLUETEAM-SECURITY-UX-20260413AK: type-to-confirm friction.
   * Require the operator to type the VMID before the CONFIRM button
   * enables. Muscle-memory click-through on a run-of-the-mill modal
   * is how operators accidentally blow away production VMs; forcing
   * them to type the identifier defeats that failure mode. */
  confirmDestructive(
    'Destroy VM <strong>'+vmid+'</strong>? All disks and snapshots will be deleted.',
    String(vmid),
    function(){
      _authFetch(API.VM_DESTROY+'?vmid='+vmid,{method:'POST'}).then(function(r){return r.json()}).then(function(d){
        if(d.ok)toast('VM '+vmid+' destroyed','success');else toast('Error: '+d.error,'error');refreshCurrentView();
      });
    }
  );
}
function vmSnap(){} /* Snapshot mutation admission unavailable. */
function vmPower(){return;} /* Unavailable: no original VM mutation admission. */
function _vmWaitForPowerState(vmid,action){
  var wantRunning=action==='start'||action==='restart';
  var wantStopped=action==='stop'||action==='shutdown';
  if(!wantRunning&&!wantStopped)return _fetchFreshVm(vmid);
  var tries=0;
  return new Promise(function(resolve,reject){
    function tick(){
      tries++;
      _fetchFreshVm(vmid).then(function(vm){
        var running=vm&&vm.status==='running';
        if((wantRunning&&running)||(wantStopped&&vm&&vm.status==='stopped')){resolve(vm);return;}
        if(tries>=24){reject(new Error('VM '+vmid+' did not settle after '+action));return;}
        setTimeout(tick,1500);
      }).catch(function(e){
        if(tries>=24){reject(e);return;}
        setTimeout(tick,1500);
      });
    }
    tick();
  });
}
function vmPushKey(ip){
  if(!ip){toast('No IP available for this VM','error');return;}
  confirmAction('Push freq SSH key to <strong>'+_esc(''+ip)+'</strong>?<br><span class="text-sm text-dim">Deploys the FREQ service account authorized_keys so FREQ can manage this host.</span>',function(){
    toast('Pushing key to '+ip+'...','info');
    /* POST + JSON body. R-SECURITY-TRUST-AUDIT-20260413P F18: the
     * pre-fix GET form mutated remote SSH state, leaked the target IP
     * via URL log channels, and depended entirely on SameSite=Strict
     * for CSRF mitigation. Server now requires POST and reads ip from
     * the JSON body. */
    _authFetch('/api/vm/push-key',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({ip:ip})}).then(function(r){return r.json()}).then(function(d){
      if(d.error){toast('Key push failed: '+d.error,'error');return;}
      toast('Key deployed to '+ip+(d.verified?' — verified':''),'success');
    }).catch(function(e){toast('Key push failed: '+e,'error');});
  });
}

