    var hostOpening=_dialogFocusOwner.begin(hostOverlay);if(!alive()||!hostOpening)return;
    var previous=_cardCommandAdmissions.get(_cardState);if(!alive())return;
    if(previous){previous.dispose();if(!alive())return;}
    var nextCard={type:type,host:config.label||'',vmid:config.vmid||0};if(!alive())return;
    _cardState=nextCard;
