    if(!_guestProfileCards.beginDialog(config,nextCard,hostOverlay,hostOpening)||!alive())return;
    if(!_fleetVmEntries.beginDialog(config,nextCard,hostOverlay,hostOpening)||!alive())return;
    if(!_clusterObservation.beginDialog(config,nextCard,hostOverlay,hostOpening)||!alive())return;
    if(config._infraContext&&(!_infraNative.beginDialog(config,nextCard,hostOverlay,hostOpening)||!alive()))return;
    if(!alive())return;_infraOutputTarget=null;
    var ov=document.getElementById('host-overlay');if(!alive())return;
