    var title=document.getElementById('hd-title');if(!alive())return;
    var label=(_displayName(config)||config.label||'').toUpperCase();if(!alive())return;
    title.textContent=label;if(!alive())return;
    var subtitle=document.getElementById('hd-subtitle');if(!alive())return;
    subtitle.textContent='Loading...';if(!alive())return;
    var loading=document.getElementById('hd-loading');if(!alive())return;
