    if(!alive())return false;
    if(_clusterObservation){_clusterObservation.retireCard();if(!alive())return false;}
    _clusterReport.retire();if(!alive())return false;
    _fleetVmEntries.retireCard();if(!alive())return false;
    _dockerHostActionRetire();if(!alive())return false;
    _retireScrubUnavailable();if(!alive())return false;
    var hostOverlay=document.getElementById('host-overlay');if(!alive())return false;
    if(!_hostPanelFocus.shell()||!alive())return false;
    if(!_dialogFocusOwner.canDismiss(hostOverlay)||!alive())return false;
    var guestClosing=_guestProfileCards.closing();if(!alive())return false;
    _guestProfileCards.retireCard();if(!alive())return false;
    var vmClosing=_fleetVmEntries.closing();if(!alive())return false;
    var clusterClosing=_clusterObservation.closing();if(!alive())return false;
    var hostWasTop=_dialogFocusOwner.top()===hostOverlay;if(!alive())return false;
    _infraNative.retireDialog(null);if(!alive())return false;
    var admission=_cardCommandAdmissions.get(_cardState);if(!alive())return false;
    if(admission){admission.dispose();if(!alive())return false;}
    var overlay=document.getElementById('host-overlay');if(!alive())return false;
    overlay.classList.remove('open');if(!alive())return false;
    /* Host scroll locking is CSS-owned; foreign body styles remain untouched. */
    _infraOutputTarget=null;
    var emptyCard={type:'',host:'',vmid:0};if(!alive())return false;
    _cardState=emptyCard;
    if(!_guestProfileCards.cardAssigned(continuation,emptyCard)||!alive())return false;
    var content=document.getElementById('hd-content');if(!alive())return false;
    content.innerHTML='';if(!alive())return false;
    _hostPanelFocus.closed();if(!alive())return false;
    _dialogFocusOwner.closed(hostOverlay,false,hostWasTop);if(!alive())return false;
    _fleetVmEntries.closed(vmClosing);if(!alive())return false;
