  h+='<div class="mb-8"><label class="label-sub-10-tight">VMID</label><div class="flex-gap-4"><input id="vm-new-id" placeholder="new ID" type="number" style="background:var(--card);border:2px solid var(--input-border);color:var(--text);padding:6px 10px;border-radius:6px;font-size:12px;font-family:inherit;width:100px"><button class="fleet-btn pill-pad6" onclick="'+handler('_vmChangeId',[vmid])+'" >SET</button></div></div>';
  h+='<div><label class="label-sub-10-tight">NETWORK CONFIG</label>';
