  if(acts.indexOf('migrate')>=0)ctrl+='<button class="fleet-btn pad-v8-fs11" onclick="'+handler('_vmToggleMigrate',[vmid,String(vm?vm.node:'')])+'" >MIGRATE</button>';
  if(acts.indexOf('destroy')>=0)ctrl+='<button class="fleet-btn btn-red pad-v8-fs11" data-action="vmDestroy" data-vmid="'+literal(vmid)+'" >DESTROY</button>';
  if(acts.length<=1)ctrl+='<span class="text-sm text-dim" style="grid-column:1/-1">View only \u2014 no actions for '+literal(catLabel)+'</span>';
  ctrl+='<div style="grid-column:1/-1;border-top:1px solid var(--input-border);margin-top:6px;padding-top:8px;font-size:11px;color:var(--text-dim);letter-spacing:0.5px">HOST TOOLS</div>';
  if(hostToolTarget){
    ctrl+='<span class="text-sm text-dim">Host command target association is unqualified.</span>';
    ctrl+='<button class="fleet-btn pad-v8-fs11" data-action="hdLogs" >LOGS</button>';
    ctrl+='<button class="fleet-btn pad-v8-fs11" data-action="hdDiagnose" >DIAGNOSE</button>';
  }else{
    ctrl+='<span class="text-sm text-dim" style="grid-column:1/-1">Host tools unavailable — no resolved SSH target for '+literal(catLabel)+'.</span>';
  }
  if(ip)ctrl+='<button class="fleet-btn pad-v8-fs11" onclick="'+handler('vmPushKey',[String(ip||'')])+'" >PUSH KEY</button>';
  if(isRunning){
    if(termIp)ctrl+='<button class="fleet-btn pad-v8-fs11" style="color:var(--cyan)" onclick="'+handler('openTerminal',['host',String(termIp),'',label?String(label):'','linux'])+'">&#9002; TERMINAL</button>';
    else ctrl+='<button class="fleet-btn pad-v8-fs11" style="color:var(--cyan)" onclick="'+handler('openTerminal',['vm',String(vmid),vm&&vm.node?String(vm.node):'',label?String(label):''])+'">&#9002; TERMINAL</button>';
  }
  ctrl+='</div></div>';
