function gwipeRefreshBays(host,pfx){
  pfx=pfx||'';
  _ltProxy('gwipe','GET','bays',function(d){
    if(d.error||!d.bays)return;var html='';
    Object.keys(d.bays).sort().forEach(function(dev,i){html+=gwipeBayCard(dev,d.bays[dev],i,pfx);});
    var el=_ltEl(pfx,'lt-content');if(el)el.innerHTML='<div class="cards grid-auto-280" >'+(html||'<div style="color:var(--text-dim);padding:24px">No bays detected</div>')+'</div>';
  });
}
function gwipeBayCard(dev,b,idx,pfx){
  pfx=pfx||'';
  function literal(value){return _esc(String(value));}
  var state=b.state||'EMPTY';
  var displayState=(state==='DETECTED')?'IDLE':state;
  var h='<div class="host-card">';
  h+='<div class="flex-between-mb8">';
  h+='<div style="font-size:16px;font-weight:700;color:var(--purple-light)">BAY '+literal((idx+1))+'</div>';
  var stBg='background:rgba(110,118,129,0.1);color:var(--text-dim)';
  if(displayState==='WIPING')stBg='background:rgba(210,153,34,0.15);color:var(--yellow)';
  else if(displayState==='WIPED'||displayState==='TESTED')stBg='background:rgba(63,185,80,0.15);color:var(--green)';
  else if(displayState==='SMART_FAILED')stBg='background:rgba(248,81,73,0.15);color:var(--red)';
  else if(displayState==='TESTING')stBg='background:rgba(86,212,221,0.15);color:var(--cyan)';
  else if(displayState==='IDLE')stBg='background:rgba(123,47,190,0.1);color:var(--purple-light)';
  h+='<div style="font-size:12px;font-weight:600;letter-spacing:1px;padding:2px 8px;border-radius:4px;'+stBg+'">'+literal(displayState)+'</div></div>';
  if(!b.present&&state!=='REMOVED'){h+='<div style="color:var(--text-dim);font-size:12px;padding:12px 0;text-align:center">No drive inserted</div><div class="text-sub">/dev/'+literal(dev)+'</div></div>';return h;}
  h+='<div style="font-size:13px;font-weight:600;color:var(--text-bright);white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="'+literal((b.model||'Unknown'))+'">'+literal((b.model||'Unknown'))+'</div>';
  h+='<div style="display:flex;gap:12px;margin-top:4px;font-size:11px;color:var(--text-dim)"><span>'+literal((b.size||'?'))+'</span><span>'+literal((b.type||'?'))+'</span><span>/dev/'+literal(dev)+'</span></div>';
  h+='<div style="margin-top:10px;padding:10px 12px;background:var(--bg);border:2px solid var(--input-border);border-radius:8px">';
  h+='<div class="text-sm text-dim" style="letter-spacing:1px;margin-bottom:6px">DRIVE IDENTITY</div>';
  h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:11px">';
  h+='<div>Serial: <strong style="font-size:14px;font-family:monospace;color:var(--text);letter-spacing:1px">'+literal((b.serial||'N/A'))+'</strong></div>';
  h+='<div>Model: <strong>'+literal((b.model||'Unknown'))+'</strong></div>';
  h+='<div>Size: <strong>'+literal((b.size||'?'))+'</strong></div>';
  h+='<div>Type: <strong>'+literal((b.type||'?'))+'</strong></div>';
  h+='</div></div>';
  if(b.smart){
    var sh=b.smart;var hc=sh.health==='PASSED'?'var(--green)':sh.health?'var(--red)':'var(--text-dim)';
    h+='<div style="margin-top:8px;padding:10px 12px;background:var(--bg);border:2px solid var(--input-border);border-radius:8px">';
    h+='<div style="font-size:12px;color:var(--cyan);letter-spacing:1px;margin-bottom:6px">SMART TEST RESULTS</div>';
    h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:11px">';
    if(sh.health)h+='<div>Health: <strong style="color:'+hc+'">'+literal(sh.health)+'</strong></div>';
    if(sh.hours)h+='<div>Power-On: <strong>'+literal(sh.hours)+'</strong></div>';
    if(sh.age)h+='<div>Age: <strong>'+literal(sh.age)+'</strong></div>';
    if(b.temp_c&&b.temp_c>0){var tc=b.temp_c;h+='<div>Temp: <strong style="color:'+(tc<=35?'var(--green)':tc<=45?'var(--yellow)':'var(--red)')+'">'+literal(tc)+'\u00b0C</strong></div>';}
    h+='</div></div>';
  } else {
    h+='<div style="margin-top:8px;padding:10px 12px;background:var(--bg);border:2px dashed var(--input-border);border-radius:8px;text-align:center">';
    h+='<div class="text-sub">Run SMART TEST to get health, hours, age, temperature</div>';
    h+='</div>';
  }
  if(state==='WIPING'&&b.wipe){var pct=b.wipe.percent||0;
    h+='<div class="mt-10"><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:3px"><span class="c-yellow">'+literal((b.wipe.method||''))+'</span><span style="color:var(--text-bright);font-weight:600">'+literal(pct.toFixed(1))+'%</span></div>';
    h+='<div style="background:rgba(255,255,255,0.06);border-radius:3px;height:6px;overflow:hidden"><div style="width:'+pct+'%;height:100%;background:linear-gradient(90deg,var(--yellow),var(--orange));border-radius:3px;transition:width 0.5s"></div></div>';
    h+='<div class="text-sm text-dim" style="display:flex;justify-content:space-between;margin-top:3px"><span>'+literal((b.wipe.speed||''))+'</span><span>ETA: '+literal((b.wipe.eta||''))+'</span></div></div>';
  }
  if(state==='WIPED'&&b.wipe)h+='<div style="margin-top:8px;padding:6px 10px;background:rgba(63,185,80,0.08);border-radius:6px;font-size:11px;color:var(--green);font-weight:600;text-align:center">CLEAN — '+literal((b.wipe.method||''))+(b.wipe.duration?' ('+literal(b.wipe.duration)+')':'')+'</div>';
  if(b.present){
    h+='<div style="margin-top:10px;display:flex;gap:6px;flex-wrap:wrap">';
    h+='<button type="button" class="fleet-btn btn-cyan pill-sm" disabled>SMART TEST UNAVAILABLE</button>';
    h+='<button type="button" class="fleet-btn btn-red pill-sm" disabled>WIPE UNAVAILABLE</button>';
    h+='<button type="button" class="fleet-btn btn-orange pill-sm" disabled>PAUSE UNAVAILABLE</button>';
    h+='<button type="button" class="fleet-btn btn-green pill-sm" disabled>RESUME UNAVAILABLE</button>';
    h+='<button type="button" class="fleet-btn" disabled>CLEAR UNAVAILABLE</button>';
    h+='</div>';
  }
  h+='</div>';
  return h;
}
