function _fedReceiptText(d){
  var label=d.operation==='poll'?'All-site registry poll':d.operation+' for '+d.name;
  if(d.outcome==='accepted')return label+': server acknowledged'+(d.operation==='toggle'?' '+(d.enabled?'enabled':'disabled'):'')+'. This is not a durable receipt or verification of remote peers.';
  if(d.outcome==='not_written')return label+': registry replacement was not written. Refresh current registry state before a deliberate next decision.';
  if(d.outcome==='refused')return label+': server refused this request. Refresh current registry state before a deliberate next decision.';
  return label+': persistence outcome unknown. The registry may have changed. Refresh current state and inspect before a deliberate next decision; no automatic retry.';
}

